// Edge Function "request-new-key" as a single file for the Supabase dashboard editor.
// Generated by scripts/build-dashboard-functions.mjs from supabase/functions/. Do not edit by hand.
// In the dashboard: Edge Functions -> Deploy a new function -> Via Editor -> name it "request-new-key",
// paste this whole file, Deploy, then switch "Verify JWT" OFF for it (this function checks the caller itself).

import { createClient, type SupabaseClient } from 'npm:@supabase/supabase-js@2';

// ---- _shared\deps.ts
// Dependency container so handlers can be unit-tested with fakes.

interface Deps {
  env: (name: string) => string | undefined;
  /** Client acting as the logged-in user (RLS applies, auth.uid() is set). */
  userClient: (token: string) => SupabaseClient;
  /** Client with only the public anon key (for verifying a password like the browser would). */
  anon: () => SupabaseClient;
  /** Service-role client. Only for work the user must not do themselves (storage, auth admin). */
  admin: () => SupabaseClient;
  fetch: typeof fetch;
  /** Run work after the response is sent (EdgeRuntime.waitUntil); awaited inline if unavailable. */
  background: (work: Promise<unknown>) => void;
  now: () => Date;
}

function need(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new Error(`Missing function secret: ${name}`);
  return v;
}

function realDeps(): Deps {
  let admin: SupabaseClient | undefined;
  return {
    env: (n) => Deno.env.get(n),
    userClient: (token) =>
      createClient(need('SUPABASE_URL'), need('SUPABASE_ANON_KEY'), {
        global: { headers: { Authorization: `Bearer ${token}` } },
        auth: { persistSession: false, autoRefreshToken: false },
      }),
    anon: () =>
      createClient(need('SUPABASE_URL'), need('SUPABASE_ANON_KEY'), {
        auth: { persistSession: false, autoRefreshToken: false },
      }),
    admin: () =>
      (admin ??= createClient(need('SUPABASE_URL'), need('SUPABASE_SERVICE_ROLE_KEY'), {
        auth: { persistSession: false, autoRefreshToken: false },
      })),
    fetch: (...a) => fetch(...a),
    background: (work) => {
      // deno-lint-ignore no-explicit-any
      const rt = (globalThis as any).EdgeRuntime;
      const guarded = work.catch((e) => console.error('background task failed', e instanceof Error ? e.message : e));
      if (rt?.waitUntil) rt.waitUntil(guarded);
    },
    now: () => new Date(),
  };
}

/** Verifies the bearer token with Supabase Auth and returns the user id. */
async function authenticate(deps: Deps, token: string | null): Promise<{ id: string; email?: string } | null> {
  if (!token) return null;
  const { data, error } = await deps.admin().auth.getUser(token);
  if (error || !data?.user) return null;
  return { id: data.user.id, email: data.user.email };
}

// ---- _shared\http.ts
// Small HTTP helpers shared by all Edge Functions.
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

/** Handles CORS preflight and non-POST methods. Returns a Response when the request is done. */
function gate(req: Request): Response | null {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders });
  if (req.method !== 'POST') return json({ error: 'method_not_allowed', message: 'Use POST.' }, 405);
  return null;
}

function bearer(req: Request): string | null {
  const h = req.headers.get('Authorization') ?? '';
  const m = /^Bearer\s+(.+)$/i.exec(h);
  return m ? m[1].trim() : null;
}

async function readJson(req: Request): Promise<Record<string, unknown> | null> {
  try {
    const body = await req.json();
    return body && typeof body === 'object' && !Array.isArray(body) ? body : null;
  } catch {
    return null;
  }
}

const STATUS_BY_CODE: Record<string, number> = {
  forbidden: 403, not_member: 403, not_found: 404, draft_not_found: 404,
  already_reviewed: 409, duplicate_reference: 409, resubmission_exists: 409, rate_limited: 429,
};

/**
 * Database errors are raised as "code: human message" (see the migrations). Known codes are passed
 * to the client; anything else is hidden behind a generic message.
 */
function dbError(error: { message?: string; code?: string; status?: number }): Response {
  const msg = error.message ?? '';
  if (error.code === 'PGRST301' || error.code === 'PGRST303' || /\bJWT\b/.test(msg)) {
    return json({ error: 'unauthorized', message: 'Please log in again.' }, 401);
  }
  const m = /^([a-z_]+): ([\s\S]*)$/.exec(msg);
  if (m) return json({ error: m[1], message: m[2] }, STATUS_BY_CODE[m[1]] ?? 400);
  if (error.code === '42501') return json({ error: 'forbidden', message: 'Not allowed.' }, 403);
  console.error('unexpected database error', error.code, msg);
  return json({ error: 'internal', message: 'Something went wrong. Please try again.' }, 500);
}

function errorResponse(code: string, message: string, status = 400): Response {
  return json({ error: code, message }, status);
}

// ---- request-new-key\handler.ts
// Public "Resend my key". Always answers with the same message so nobody can probe which emails
// are registered. Rate limited per email and per IP in the database.


const GENERIC_MESSAGE = 'If this email is registered, a new key has been sent.';

function clientIp(req: Request): string | null {
  const fwd = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim();
  return fwd || req.headers.get('cf-connecting-ip') || null;
}

async function handle(req: Request, deps: Deps): Promise<Response> {
  const early = gate(req);
  if (early) return early;

  const body = await readJson(req);
  const email = typeof body?.email === 'string' ? body.email.trim().toLowerCase() : '';
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) || email.length > 254) {
    return errorResponse('invalid_email', 'Enter a valid email address.');
  }
  const ip = clientIp(req);

  // Do the work after replying, so response time never reveals whether the email is registered.
  deps.background(forwardToAppsScript(deps, email, ip));
  return json({ message: GENERIC_MESSAGE });
}

async function forwardToAppsScript(deps: Deps, email: string, ip: string | null): Promise<void> {
  const admin = deps.admin();
  const { data: allowed, error } = await admin.rpc('rate_limit_key_request', { p_email: email, p_ip: ip });
  if (error || allowed !== true) return;

  const { data: member } = await admin.from('members').select('id').eq('email', email).eq('active', true).maybeSingle();
  if (!member) return;

  const url = deps.env('APPS_SCRIPT_URL');
  const secret = deps.env('RESEND_SHARED_SECRET');
  if (!url || !secret) {
    console.error('APPS_SCRIPT_URL / RESEND_SHARED_SECRET are not configured');
    return;
  }
  // Apps Script cannot read headers, so the shared secret goes in the (HTTPS) JSON body.
  const res = await deps.fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ secret, email }),
    redirect: 'follow',
  });
  const text = await res.text();
  if (!res.ok || text.trim() !== 'ok') console.error('apps script resend failed', res.status, text.slice(0, 80));
}

// ---- request-new-key\index.ts
const deps = realDeps();
Deno.serve((req) => handle(req, deps));
